"""Add Two Numbers — schoolbook addition, digits already reversed.

Time: O(max(n, m))   Space: O(1) beyond the output
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def addTwoNumbers(self, l1, l2):
        sentinel = ListNode()
        tail, carry = sentinel, 0
        while l1 or l2 or carry:
            total = carry
            if l1:
                total += l1.val
                l1 = l1.next
            if l2:
                total += l2.val
                l2 = l2.next
            carry, digit = divmod(total, 10)
            tail.next = ListNode(digit)
            tail = tail.next
        return sentinel.next
